public final class TcpSegment{private final int sourcePort;private final int destinationPort;private final long sequence;private final long acknowledgment;private final int flags;private final byte[] payload;private final List<String> flagNames;public TcpSegment(int sourcePort,int destinationPort,long sequence,long acknowledgment,int flags,byte[] payload,List<String> flagNames){this.sourcePort=sourcePort;this.destinationPort=destinationPort;this.sequence=sequence;this.acknowledgment=acknowledgment;this.flags=flags;this.payload=payload==null?new byte[0]:payload;this.flagNames=flagNames;}public static ParseResult<TcpSegment> parse(byte[] data){Diagnostics d=new Diagnostics();if(data==null||data.length<20)return ParseResult.failure("tcp.truncated","TCP header truncated");int sp=Endian.u16be(data,0);int dp=Endian.u16be(data,2);long seq=Endian.u32be(data,4);long ack=Endian.u32be(data,8);int off=((data[12]&255)>>>4)*4;if(off<20||off>data.length)return ParseResult.failure("tcp.offset","invalid TCP data offset");int flags=((data[12]&1)<<8)|(data[13]&255);List<String> names=flags(flags);if(names.contains("SYN")&&names.contains("FIN"))d.medium("tcp.flags","SYN and FIN both set");return ParseResult.of(new TcpSegment(sp,dp,seq,ack,flags,SafeSlice.copy(data,off,data.length-off),names),d);}private static List<String> flags(int flags){List<String> n=new ArrayList<>();if((flags&0x100)!=0)n.add("NS");if((flags&0x080)!=0)n.add("CWR");if((flags&0x040)!=0)n.add("ECE");if((flags&0x020)!=0)n.add("URG");if((flags&0x010)!=0)n.add("ACK");if((flags&0x008)!=0)n.add("PSH");if((flags&0x004)!=0)n.add("RST");if((flags&0x002)!=0)n.add("SYN");if((flags&0x001)!=0)n.add("FIN");return n;}public int sourcePort(){return sourcePort;}public int destinationPort(){return destinationPort;}public long sequence(){return sequence;}public long acknowledgment(){return acknowledgment;}public int flags(){return flags;}public byte[] payload(){return payload;}public List<String> flagNames(){return java.util.Collections.unmodifiableList(flagNames);}}
